pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (very tight fits) 
    // if they leave a gap that is likely unusable (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global State Balancing: Avoid fragmenting if possible. 
    // Reward placing in bins that bring the bin closer to the global mean residual.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 4. New Bin Logic: Discourage opening new bins unless necessary or 
    // if the existing bins are all high-fragmentation traps.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one works,
            // unless the progression is late and we need to consolidate.
            score += 60.0 + (progress * 20.0);
        } else {
            // If no bins fit, this is mandatory; set score low.
            score = 0.0;
        }
    } else {
        // 5. Multi-bin Pressure: If many bins are open, favor filling the 
        // most empty ones to keep the number of active bins constrained.
        score += (open_bins_count as f64) * 2.0;

        // Reward filling bins that are already quite full (Best-Fit principle).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // prioritize this bin heavily to keep the bin compact.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. If this is the only bin that can fit the current item, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 4. If deciding whether to open a new bin (bin_residual == bin_capacity):
    // Only open a new bin if we have many bins open and the mean_residual is low,
    // indicating that we are already effectively utilizing space.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 30.0; // Discourage opening new bins if existing ones have space
        } else {
            score += 10.0; // Neutral baseline for opening a new bin
        }
    }

    // 5. Global progression factor: As we approach the end of the stream, 
    // tighten the requirements for packing to reduce total bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Core objective: Minimize post_residual (Best Fit)
    // Penalty for creating "dead space": small residuals that are too small to fit future items.
    // We use a non-linear penalty for residuals in the range (0, 10), which are highly likely to be wasted.
    let dead_space_penalty = if post_residual > 0 && post_residual < 15 {
        (15.0 - post_res).powi(2) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, favor bins that have enough space left.
    // If post_residual < next_item_size, we penalize the bin because it forces a new bin later.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 1.5
    } else {
        0.0
    };

    // Global state awareness: 
    // As the stream progresses (progress -> 1.0), we become more conservative about opening new bins.
    // We reward filling bins that are already "half-full" (closer to mean_residual).
    let deviation_from_mean = (post_res - mean_residual).abs();
    let efficiency_bias = deviation_from_mean * progress;

    // New bin logic:
    // If bin_residual == bin_capacity, this is a candidate for opening a new bin.
    // We set a threshold cost for opening a new bin that increases with progress.
    let new_bin_cost = if bin_residual == bin_capacity {
        50.0 + (progress * 40.0) - (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Combine terms:
    // Lower score is better.
    post_res + dead_space_penalty + lookahead_penalty + efficiency_bias + new_bin_cost
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are small but non-zero (fragments)
    // as these are notoriously hard to fill later. 
    // If post_residual is in the range [1, 9], it's a "bad" fragment.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, 
    // significantly lower the score (rewarding potential pairings).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one 
    // unless the fit is perfect (post_residual == 0).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if post_residual != 0 {
            score += 60.0;
        }
    }

    // 4. Harmonic Alignment: Favor bins where the post_residual is a multiple 
    // of common item sizes (e.g., 20, 25) to increase likelihood of future fits.
    if post_residual > 0 && (post_residual % 20 == 0 || post_residual % 25 == 0) {
        score -= 10.0;
    }

    // 5. Scarcity Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Global Trend: As we approach the end of the stream, prioritize 
    // filling existing bins over creating new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}
